from decimal import Decimal, ROUND_HALF_EVEN

def charge_amount(cents: int, fx_rate: float) -> int:
    """Convert cents using fx_rate with banker's rounding (ROUND_HALF_EVEN)."""
    amount = Decimal(cents) * Decimal(str(fx_rate))
    rounded = amount.quantize(Decimal('1'), rounding=ROUND_HALF_EVEN)
    return int(rounded)

